namespace RecipeCommunity.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

public static class RecipeData
{
    public static List<Recipe> Recipes { get; } = new()
    {
        new Recipe { Id = 1, Title = "Classic Margherita Pizza", Category = "Italian", Ingredients = "Pizza dough, San Marzano tomatoes, Fresh mozzarella, Fresh basil, Olive oil, Salt", Steps = "1. Preheat oven to 475°F.
2. Roll out dough on floured surface.
3. Spread crushed tomatoes evenly.
4. Tear mozzarella and distribute.
5. Bake 10-12 minutes until crust is golden.
6. Top with fresh basil and drizzle olive oil.", AverageRating = 4.5, RatingCount = 12 },
        new Recipe { Id = 2, Title = "Chicken Tikka Masala", Category = "Indian", Ingredients = "Chicken thighs, Yogurt, Garam masala, Cumin, Tomato sauce, Heavy cream, Garlic, Ginger, Onion", Steps = "1. Marinate chicken in yogurt and spices for 2 hours.
2. Grill or broil chicken until charred.
3. Sauté onion, garlic, and ginger.
4. Add tomato sauce and simmer.
5. Stir in cream and spices.
6. Add chicken and simmer 10 minutes.", AverageRating = 4.8, RatingCount = 20 },
        new Recipe { Id = 3, Title = "Beef Tacos", Category = "Mexican", Ingredients = "Ground beef, Taco shells, Lettuce, Tomato, Cheddar cheese, Sour cream, Taco seasoning", Steps = "1. Brown ground beef in skillet.
2. Add taco seasoning and water, simmer 5 minutes.
3. Warm taco shells.
4. Assemble with beef, lettuce, tomato, cheese.
5. Top with sour cream.", AverageRating = 4.2, RatingCount = 8 },
        new Recipe { Id = 4, Title = "Pad Thai", Category = "Thai", Ingredients = "Rice noodles, Shrimp, Eggs, Bean sprouts, Green onions, Peanuts, Tamarind paste, Fish sauce, Sugar, Lime", Steps = "1. Soak rice noodles in warm water 30 minutes.
2. Stir-fry shrimp until pink, set aside.
3. Scramble eggs in wok.
4. Add noodles and sauce (tamarind, fish sauce, sugar).
5. Toss with shrimp and bean sprouts.
6. Serve with peanuts and lime.", AverageRating = 4.6, RatingCount = 15 },
        new Recipe { Id = 5, Title = "Chocolate Lava Cake", Category = "Desserts", Ingredients = "Dark chocolate, Butter, Eggs, Sugar, Flour, Vanilla extract", Steps = "1. Melt chocolate and butter together.
2. Whisk eggs and sugar until thick.
3. Fold in chocolate mixture.
4. Add flour and vanilla.
5. Pour into greased ramekins.
6. Bake at 425°F for 12 minutes.
7. Invert onto plates and serve immediately.", AverageRating = 4.9, RatingCount = 25 },
        new Recipe { Id = 6, Title = "Caesar Salad", Category = "Salads", Ingredients = "Romaine lettuce, Parmesan cheese, Croutons, Caesar dressing, Lemon juice, Anchovies, Garlic", Steps = "1. Wash and chop romaine lettuce.
2. Make dressing: blend anchovies, garlic, lemon, and parmesan.
3. Toss lettuce with dressing.
4. Top with croutons and shaved parmesan.", AverageRating = 4.0, RatingCount = 6 },
    };

    public static List<string> Categories => Recipes.Select(r => r.Category).Distinct().ToList();
}

@rendermode InteractiveServer

<div class="star-rating">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= CurrentRating ? "filled" : "")"
              @onclick="() => Rate(star)"
              role="button">
            @(star <= CurrentRating ? "★" : "☆")
        </span>
    }
    <span class="rating-info ms-2">
        (@AverageRating.ToString("F1") avg, @RatingCount ratings)
    </span>
</div>

@if (UserRated)
{
    <div class="alert alert-success mt-2 py-1 px-2 small">Thanks for rating!</div>
}

@code {
    [Parameter] public double AverageRating { get; set; }
    [Parameter] public int RatingCount { get; set; }

    private int CurrentRating { get; set; }
    private bool UserRated { get; set; }

    protected override void OnParametersSet()
    {
        CurrentRating = (int)Math.Round(AverageRating);
    }

    private void Rate(int stars)
    {
        CurrentRating = stars;
        UserRated = true;
        // In production, persist rating to a database
    }
}

@page "/recipe/{Id:int}"
@using RecipeCommunity.Models

<PageTitle>@recipe?.Title - Recipe Community</PageTitle>

@if (recipe is null)
{
    <div class="alert alert-warning">Recipe not found.</div>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="/recipes/@recipe.Category">@recipe.Category</a></li>
            <li class="breadcrumb-item active">@recipe.Title</li>
        </ol>
    </nav>

    <h1>@recipe.Title</h1>
    <span class="badge bg-secondary mb-3">@recipe.Category</span>

    <StarRating AverageRating="@recipe.AverageRating" RatingCount="@recipe.RatingCount" />

    <div class="row mt-4">
        <div class="col-md-4">
            <div class="card">
                <div class="card-header"><h5 class="mb-0">Ingredients</h5></div>
                <ul class="list-group list-group-flush">
                    @foreach (var ingredient in recipe.Ingredients.Split(',', StringSplitOptions.TrimEntries))
                    {
                        <li class="list-group-item">@ingredient</li>
                    }
                </ul>
            </div>
        </div>
        <div class="col-md-8">
            <h4>Instructions</h4>
            @foreach (var step in recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
            {
                <p>@step</p>
            }
        </div>
    </div>
}

@code {
    [Parameter] public int Id { get; set; }

    private Recipe? recipe;

    protected override void OnInitialized()
    {
        recipe = RecipeData.Recipes.FirstOrDefault(r => r.Id == Id);
    }
}

@page "/recipes/{Category}"
@using RecipeCommunity.Models

<PageTitle>@Category Recipes - Recipe Community</PageTitle>

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        <li class="breadcrumb-item active">@Category</li>
    </ol>
</nav>

<h1>@Category Recipes</h1>

@if (!recipes.Any())
{
    <p class="text-muted">No recipes found in this category.</p>
}
else
{
    <div class="row">
        @foreach (var recipe in recipes)
        {
            <div class="col-md-6 col-lg-4 mb-4">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text text-muted small">
                            ★ @recipe.AverageRating.ToString("F1") (@recipe.RatingCount ratings)
                        </p>
                        <a href="/recipe/@recipe.Id" class="btn btn-outline-primary btn-sm">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    [Parameter] public string Category { get; set; } = string.Empty;

    private List<Recipe> recipes = new();

    protected override void OnInitialized()
    {
        recipes = RecipeData.Recipes
            .Where(r => r.Category.Equals(Category, StringComparison.OrdinalIgnoreCase))
            .ToList();
    }
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeCommunity.Models

<PageTitle>Submit a Recipe - Recipe Community</PageTitle>

<h1>Submit a Recipe</h1>
<p class="text-muted">Share your favorite recipe with the community!</p>

@if (Submitted)
{
    <div class="alert alert-success">
        <h4>Recipe Submitted!</h4>
        <p>Thank you for sharing "<strong>@Model.Title</strong>" with the community.</p>
        <a href="/" class="btn btn-primary">Back to Home</a>
    </div>
}
else
{
    <EditForm Model="@Model" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
        <DataAnnotationsValidator />
        <ValidationSummary class="text-danger" />

        <div class="mb-3">
            <label for="title" class="form-label">Recipe Title</label>
            <InputText id="title" class="form-control" @bind-Value="Model.Title" placeholder="e.g., Grandma's Apple Pie" />
            <ValidationMessage For="@(() => Model.Title)" />
        </div>

        <div class="mb-3">
            <label for="category" class="form-label">Category</label>
            <InputSelect id="category" class="form-select" @bind-Value="Model.Category">
                <option value="">-- Select Category --</option>
                @foreach (var cat in RecipeData.Categories)
                {
                    <option value="@cat">@cat</option>
                }
                <option value="Other">Other</option>
            </InputSelect>
            <ValidationMessage For="@(() => Model.Category)" />
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients</label>
            <InputTextArea id="ingredients" class="form-control" rows="5" @bind-Value="Model.Ingredients"
                placeholder="One ingredient per line" />
            <ValidationMessage For="@(() => Model.Ingredients)" />
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps</label>
            <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="Model.Steps"
                placeholder="Describe each step..." />
            <ValidationMessage For="@(() => Model.Steps)" />
        </div>

        <button type="submit" class="btn btn-success">Submit Recipe</button>
    </EditForm>
}

@code {
    [SupplyParameterFromForm]
    private RecipeFormModel Model { get; set; } = new();

    private bool Submitted { get; set; }

    private void HandleSubmit()
    {
        // In production, save to database
        Submitted = true;
    }

    public class RecipeFormModel
    {
        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Title is required")]
        [System.ComponentModel.DataAnnotations.StringLength(100)]
        public string Title { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Category is required")]
        public string Category { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Ingredients are required")]
        public string Ingredients { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Steps are required")]
        public string Steps { get; set; } = string.Empty;
    }
}

